INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'layali-events-case-1', 'Exhibition World Bahrain Tech Pavilion', 'جناح التقنية بمركز البحرين العالمي للمعارض', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Sakhir with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Sakhir وفق أعلى معايير الجودة والالتزام.', 6800, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://layalibh.com/work/layali-events-case-1', 'Sakhir, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'layali-events-2026-outlook', 'Layali Events 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — ليالي للفعاليات', 'Key operational benchmarks, real metrics, and 2026 guidance from Layali Events in Sakhir.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من ليالي للفعاليات في Sakhir.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Turnkey event production partner delivering international summits, exhibition pavilions, and live concert staging. Focusing on LED Wall & Stage Truss Rigging, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شريك متكامل لإنتاج الفعاليات والمؤتمرات الدولية وأجنحة المعارض وتجهيز المسارح. من خلال خدمة تجهيز شاشات LED وهياكل المسارح نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Turnkey event production partner delivering international summits, exhibition pavilions, and live concert staging.</p><p>Focusing on <strong>LED Wall & Stage Truss Rigging</strong>, our Sakhir specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شريك متكامل لإنتاج الفعاليات والمؤتمرات الدولية وأجنحة المعارض وتجهيز المسارح.</p><p>من خلال خدمة <strong>تجهيز شاشات LED وهياكل المسارح</strong>، يعمل فريقنا في Sakhir على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Layali Events 2026 GCC Market Outlook & Benchmarks | Layali Events', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — ليالي للفعاليات | ليالي للفعاليات', 'Executive guide by Layali Events covering LED Wall & Stage Truss Rigging benchmarks in Bahrain.', 'دليل تنفيذي من ليالي للفعاليات حول معايير تجهيز شاشات LED وهياكل المسارح في البحرين.', 'Insights', '{"events","insights","Sakhir","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Layali Events initiate a LED Wall & Stage Truss Rigging engagement?', 'كم يستغرق بدء تنفيذ خدمة تجهيز شاشات LED وهياكل المسارح لدى ليالي للفعاليات؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Sakhir.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Sakhir.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'layali-events-case-2', 'Gulf FinTech Leadership Awards 600 Pax', 'حفل جوائز الريادة المالية لـ600 مدعو', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Sakhir with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Sakhir وفق أعلى معايير الجودة والالتزام.', 15600, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://layalibh.com/work/layali-events-case-2', 'Sakhir, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'layali-events-service-standards', 'Inside Our Staging SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في تجهيز شاشات LED وهياكل المسارح', 'Key operational benchmarks, real metrics, and 2026 guidance from Layali Events in Sakhir.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من ليالي للفعاليات في Sakhir.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Turnkey event production partner delivering international summits, exhibition pavilions, and live concert staging. Focusing on Custom Exhibition Pavilion Build, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شريك متكامل لإنتاج الفعاليات والمؤتمرات الدولية وأجنحة المعارض وتجهيز المسارح. من خلال خدمة بناء جناح معرض مخصص نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Turnkey event production partner delivering international summits, exhibition pavilions, and live concert staging.</p><p>Focusing on <strong>Custom Exhibition Pavilion Build</strong>, our Sakhir specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شريك متكامل لإنتاج الفعاليات والمؤتمرات الدولية وأجنحة المعارض وتجهيز المسارح.</p><p>من خلال خدمة <strong>بناء جناح معرض مخصص</strong>، يعمل فريقنا في Sakhir على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Staging SLA: Speed, Quality & Auditability | Layali Events', 'معايير اتفاقية مستوى الخدمة والجودة في تجهيز شاشات LED وهياكل المسارح | ليالي للفعاليات', 'Executive guide by Layali Events covering Custom Exhibition Pavilion Build benchmarks in Bahrain.', 'دليل تنفيذي من ليالي للفعاليات حول معايير بناء جناح معرض مخصص في البحرين.', 'Operations', '{"events","operations","Sakhir","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-149330-1 and VAT ID 200014933000002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-149330-1 والرقم الضريبي 200014933000002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
