"id":"cat-7","slug":"decor","name_en":"Decor","name_ar":"Decor","display_order":7,"featured":false,"is_active":true},{"id":"cat-8","slug":"registration","name_en":"Registration","name_ar":"Registration","display_order":8,"featured":false,"is_active":true}]', true, true, 'Fast delivery across Bahrain — Layali Events Official Store', 'توصيل سريع في جميع أنحاء البحرين — متجر ليالي للفعاليات الرسمي', 'CR-149330-1', '200014933000002', 14, true, true, true, now()) ON CONFLICT (id) DO UPDATE SET delivery_enabled = EXCLUDED.delivery_enabled, pickup_enabled = EXCLUDED.pickup_enabled, guest_checkout = EXCLUDED.guest_checkout, bank_instructions_en = EXCLUDED.bank_instructions_en, bank_instructions_ar = EXCLUDED.bank_instructions_ar, payment_gateway = EXCLUDED.payment_gateway, loyalty_enabled = EXCLUDED.loyalty_enabled, wallet_enabled = EXCLUDED.wallet_enabled, raffle_enabled = EXCLUDED.raffle_enabled, announcement_en = EXCLUDED.announcement_en, announcement_ar = EXCLUDED.announcement_ar, cr_number = EXCLUDED.cr_number, vat_number = EXCLUDED.vat_number, raffle_prize_en = EXCLUDED.raffle_prize_en, raffle_prize_ar = EXCLUDED.raffle_prize_ar, custom_categories_json = EXCLUDED.custom_categories_json, updated_at = now();
